import{_ as e,o,c as t,a5 as s}from"./chunks/framework.DJo0M80U.js";const g=JSON.parse('{"title":"路径问题","description":"Web Worker 的限制 ： new Worker() 接受一个 URL 字符串（例如 /workers/orderWorker.js），表示 Worker 文件的实际路径。 @ 别名是 Vite 的构建时特性，仅适用于模块导入（import 语句）， 不适用于 new Wo。","frontmatter":{"title":"路径问题","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","进阶语言能力"],"description":"Web Worker 的限制 ： new Worker() 接受一个 URL 字符串（例如 /workers/orderWorker.js），表示 Worker 文件的实际路径。 @ 别名是 Vite 的构建时特性，仅适用于模块导入（import 语句）， 不适用于 new Wo。","sidebarWeight":46,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/webworkers/核心踩坑清单/路径问题.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/07-进阶语言能力/核心踩坑清单/路径问题.md","filePath":"posts/JavaScript系统教程/07-进阶语言能力/核心踩坑清单/路径问题.md"}'),i={name:"posts/JavaScript系统教程/07-进阶语言能力/核心踩坑清单/路径问题.md"};function l(n,r,p,a,u,k){return o(),t("div",null,[...r[0]||(r[0]=[s('<div><h1 id="路径问题" tabindex="-1">路径问题 <a class="header-anchor" href="#路径问题" aria-label="Permalink to &quot;路径问题&quot;">​</a></h1><blockquote><p>本节目标：理解“路径问题”的核心思路，并能把它用于实际开发或面试表达。 <strong>Web Worker 的限制</strong>：</p></blockquote><ul><li><p>new Worker() 接受一个 URL 字符串（例如 /workers/orderWorker.js），表示 Worker 文件的实际路径。</p></li><li><p>@ 别名是 Vite 的构建时特性，仅适用于模块导入（import 语句），<strong>不适用于 new Worker() 的路径参数</strong>。</p></li><li><p>原因：new Worker() 的路径是在运行时解析的，浏览器需要实际的 URL（如 /workers/orderWorker.js），而 @ 别名在运行时不可用。</p></li><li><p>替代方案：使用 import.meta.url 或硬编码编译后的路径（如 /workers/orderWorker.js）。 <strong>分析</strong></p></li><li><p><strong>Vite 中的 import.meta</strong>：</p><ul><li>Vite 支持 import.meta.url，返回当前模块的 URL，适用于动态构造 Worker 路径。</li><li>示例：new URL(&#39;./workers/orderWorker.js&#39;, import.meta.url) 创建相对于当前模块的 Worker 路径。</li></ul></li><li><p><strong>优势</strong>：</p><ul><li>动态路径：避免硬编码 /workers/orderWorker.js，适应不同构建配置。</li><li>模块化：与 Vite 的模块系统兼容，支持 TypeScript 和路径别名。</li></ul></li><li><p><strong>限制</strong>：</p><ul><li>需要确保 Worker 文件在构建后位于正确的相对路径。</li><li>浏览器支持：import.meta.url 在现代浏览器（Chrome、Firefox、Safari）中广泛支持。</li></ul></li><li><p><strong>使用场景</strong>：</p><ul><li>当 Worker 文件位于 src/workers/，并通过 Vite 编译到 dist/workers/。</li><li>示例： typescriptCopyconst worker = new Worker(new URL(&#39;../workers/orderWorker.js&#39;, import.meta.url), { type: &#39;module&#39; });</li><li>{ type: &#39;module&#39; }：如果 orderWorker.ts 使用 ES 模块语法（如 import），需指定 Worker 类型为 module。</li></ul></li></ul><p><strong>实现</strong></p><ul><li>在 useOpenOrder.ts 中，使用 import.meta.url： typescriptCopyconst worker = new Worker(new URL(&#39;../workers/orderWorker.js&#39;, import.meta.url), { type: &#39;module&#39; });</li><li><strong>说明</strong>： <ul><li>../workers/orderWorker.js：相对于 src/composables/useOpenOrder.ts，指向 src/workers/orderWorker.js。</li><li>Vite 编译后，orderWorker.js 输出到 dist/workers/，URL 自动解析为 /workers/orderWorker.js。</li><li>{ type: &#39;module&#39; }：支持 orderWorker.ts 中的 import 语句。</li></ul></li></ul><p><strong>Vite 配置</strong></p><ul><li>确保 orderWorker.ts 编译到正确路径： typescriptCopy_// vite.config.ts_import { defineConfig } from &#39;vite&#39;;import vue from &#39;@vitejs/plugin-vue&#39;;import path from &#39;path&#39;;export default defineConfig({ plugins: [vue()], resolve: { alias: { &#39;@&#39;: path.resolve(__dirname, &#39;./src&#39;), }, }, build: { rollupOptions: { output: { assetFileNames: (assetInfo) =&gt; { if (assetInfo.name?.endsWith(&#39;orderWorker.js&#39;)) { return &#39;workers/[name].[hash][extname]&#39;; } return &#39;assets/[name].[hash][extname]&#39;; }, }, }, },});</li></ul><p><strong>结论</strong></p><ul><li><strong>可以使用 import.meta.url</strong>：推荐用于动态加载 Worker，适应模块化开发。</li><li><strong>注意事项</strong>： <ul><li>确保 Worker 文件路径正确（编译后为 /workers/orderWorker.js）。</li><li>使用 { type: &#39;module&#39; } 支持 ES 模块。</li></ul></li></ul><p><strong>最佳实践</strong><strong>最佳 Worker 导入方式</strong></p><ol><li><strong>使用 import.meta.url</strong>： <ul><li><strong>代码</strong>： const worker = new Worker(new URL(&#39;../workers/orderWorker.js&#39;, import.meta.url), { type: &#39;module&#39; });</li><li><strong>优点</strong>： <ul><li>动态路径，避免硬编码。</li><li>支持模块化 Worker（import 语句）。</li><li>与 Vite 的模块系统兼容。</li></ul></li><li><strong>适用场景</strong>：orderWorker.ts 使用 TypeScript 和 ES 模块，位于 src/workers/。</li></ul></li><li><strong>Vite 配置</strong>： <ul><li>配置 resolve.alias 和 build.rollupOptions 确保 Worker 文件编译到 /workers/。</li><li>示例： resolve: { alias: { &#39;@&#39;: path.resolve(__dirname, &#39;./src&#39;), },},build: { rollupOptions: { output: { assetFileNames: (assetInfo) =&gt; { if (assetInfo.name?.endsWith(&#39;orderWorker.js&#39;)) { return &#39;workers/[name].[hash][extname]&#39;; } return &#39;assets/[name].[hash][extname]&#39;; }, }, },}</li></ul></li><li><strong>文件位置</strong>： <ul><li><strong>推荐</strong>：src/workers/orderWorker.ts。</li><li><strong>理由</strong>：支持 TypeScript、模块化、类型安全，便于维护。</li><li><strong>编译输出</strong>：dist/workers/orderWorker.js。</li></ul></li></ol><p><strong>为什么不用 @ 别名</strong></p><ul><li>@ 别名仅适用于构建时的 import 语句，new Worker() 需要运行时 URL。</li><li>替代方案：import.meta.url 提供动态路径解析，功能等价且更灵活。</li></ul><p><strong>为什么推荐 import.meta.url</strong></p><ul><li><strong>动态性</strong>：适应不同构建配置，避免硬编码路径。</li><li><strong>模块化</strong>：支持 ES 模块 Worker（import 语句）。</li><li><strong>兼容性</strong>：与 Vite 和 TypeScript 无缝集成。</li><li><strong>维护性</strong>：减少路径错误，提升代码可读性。</li></ul></div>',1)])])}const d=e(i,[["render",l]]);export{g as __pageData,d as default};
